+import type { ConfigurableTrait, Trait } from '../trait/types';
+import { $aspect } from './symbols';
+import type { Aspect, AspectInput, AspectRecord } from './types';
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return !!(value as Aspect | undefined)?.[$aspect];
+}
+
+export function createAspect<T extends readonly [AspectInput, AspectInput, ...AspectInput[]]>(
+    ...inputs: T
+): Aspect<FlattenAspectInputs<T>> {
+    const traits: Trait[] = [];
+    const fields = new Set<string>();
+    const schema: Record<string, unknown> = {};
+
+    for (const input of inputs) {
+        const constituents = isAspect(input) ? input.traits : [input];
+        for (const constituent of constituents) {
+            if (constituent[$internal].relation) {
+                throw new Error('Koota: Relations cannot be constituents of an aspect.');
+            }
+            for (const field of Object.keys(constituent.schema)) {
+                if (fields.has(field)) {
+                    throw new Error(`Koota: Aspect constituents cannot share the field "${field}".`);
+                }
+                fields.add(field);
+                schema[field] = (constituent.schema as Record<string, unknown>)[field];
+            }
+            traits.push(constituent);
+        }
+    }
+
+    const id = aspectId++;
+    return Object.assign((params?: Partial<AspectRecord>) => [aspect, params ?? {}], {
+        id,
+        traits: Object.freeze(traits),
+        schema: Object.freeze(schema),
+        [$aspect]: true as const,
+    }) as Aspect<FlattenAspectInputs<T>>;
+
+    // The function closes over this distinct aspect instance.
+    function aspect(params?: Partial<AspectRecord>) {
+        return [aspect, params ?? {}] as [Aspect, Partial<AspectRecord>];
+    }
+}
+
+export function hasAspect(world: World, entity: Entity, aspect: Aspect) {
+    return aspect.traits.every((trait) => hasTrait(world, entity, trait));
+}
+
+export function getAspect(world: World, entity: Entity, aspect: Aspect) {
+    if (!hasAspect(world, entity, aspect)) return undefined;
+    return Object.assign({}, ...aspect.traits.map((trait) => getTrait(world, entity, trait)));
+}
+
+export function setAspect(world: World, entity: Entity, aspect: Aspect, value: any, triggerChanged = true) {
+    value instanceof Function && (value = value(getAspect(world, entity, aspect)));
+    for (const trait of aspect.traits) {
+        const fields = pickFields(trait, value);
+        if (Object.keys(fields).length) setTrait(world, entity, trait, fields, triggerChanged);
+    }
+}
+
+export function aspectTraits(aspect: Aspect, value: any): ConfigurableTrait[] {
+    return aspect.traits.map((trait) => {
+        const fields = pickFields(trait, value);
+        return Object.keys(fields).length ? [trait, fields] : trait;
+    });
+}
+
+export function pickFields(trait: Trait, value: Record<string, unknown> = {}) {
+    const result: Record<string, unknown> = {};
+    for (const field of Object.keys(trait.schema)) {
+        if (field in value) result[field] = value[field];
+    }
+    return result;
+}
+
+type FlattenAspectInput<T> = T extends Aspect<infer Traits> ? Traits[number] : T extends Trait ? T : never;
+type FlattenAspectInputs<T extends readonly AspectInput[]> = {
+    [K in keyof T]: FlattenAspectInput<T[K]>;
+} extends infer Items
+    ? Items extends readonly Trait[]
+        ? Items
+        : never
+    : never;
